import sys; sys.path.insert(0,'_exp')
from ins import ins, D
p='x6/lines.py'; s=open(p,encoding='utf-8').read(); assert 'C16g' not in s
blk=(
D('C16g','claude_point','再练一道：2017–2018 期中第 7 题，15 分。已知 v₁、v₂、v₃ 和 u₁、u₂、u₃，求 {v} 到 {u} 的过渡矩阵，再求 x = 2v₁ + 3v₂ − 4v₃ 的 u 坐标。','再练一道：二零一七到二零一八学年期中，第七题，十五分。给了v一、v二、v三，和u一、u二、u三，求从v到u的过渡矩阵，再求x等于二v一加三v二减四v三，在u下的坐标。')+
D('C16h','claude_explain','套路一样：S = U⁻¹V。把 [U | V] 并排——左边 U 的三列是 u，右边 V 的三列是 v。','套路一模一样：S等于U的逆乘V。把U和V并排写，左边U的三列是三个u，右边V的三列是三个v。')+
D('C16i','claude_explain','R₃ − R₂：左边 (0, 0, 1)，右边 (1, 0, 1)。R₂ − R₁：左边 (0, 1, 1)，右边 (2, 1, 1)。','第三行减第二行：左边得到零、零、一，右边得到一、零、一。第二行减第一行：左边得到零、一、一，右边得到二、一、一。')+
D('C16j','claude_explain','R₂ − R₃：第 2 行变成 (0, 1, 0 | 1, 1, 0)。最后 R₁ − R₂ − 2R₃：第 1 行变成 (1, 0, 0 | 1, −1, −2)。','第二行减第三行：变成零、一、零，竖线后是一、一、零。最后，第一行减第二行，再减两倍第三行：变成一、零、零，竖线后是一、负一、负二。')+
D('C16k','claude_point','左边成了 I，右边就是 S = [[1, −1, −2], [1, 1, 0], [1, 0, 1]]。','左边成了单位矩阵，右边就是S：第一行一、负一、负二；第二行一、一、零；第三行一、零、一。')+
D('C16l','claude_explain','x 的 v 坐标是 (2, 3, −4)。S 乘它：2 − 3 + 8 = 7；2 + 3 = 5；2 − 4 = −2。u 坐标 (7, 5, −2)。','x在v下的坐标是二、三、负四。S乘它：第一行，二减三加八，等于七；第二行，二加三，等于五；第三行，二减四，等于负二。所以u坐标是七、五、负二。')+
D('G03b','gpt_point','自检：7u₁ + 5u₂ − 2u₃ = (8, 11, 9)；2v₁ + 3v₂ − 4v₃ = (8, 11, 9)。同一个点，两副眼镜。','自检：七u一加五u二减二u三，等于八、十一、九；二v一加三v二减四v三，也是八、十一、九。同一个点，两副眼镜。')+
D('D04a','ds_happy','四步消元就出来了，我也会了！','四步消元就出来了，我也会了！',mood='easy')+
D('C16m','claude_point','同一题型：2020–2021 期中第 5 题，15 分。V = {(1, 0, 1), (1, 1, 0), (0, 1, 1)}，U = {(2, 3, 1), (1, 2, 0), (2, 0, 3)}。(1) 证明都是基；(2) 求 V 到 U 的过渡矩阵。','同一个题型：二零二零到二零二一学年期中，第五题，十五分。给了两组向量V和U。第一问，证明它们都是R三的基；第二问，求从V到U的过渡矩阵。')+
D('C16n','claude_explain','(1)：三个向量排成方阵算行列式。det V = 2，det U = −1，都不为 0。三个无关向量，在 R³ 里就是基。','第一问：把三个向量排成方阵，算行列式。V的行列式是二，U的行列式是负一，都不为零。三个线性无关的向量，在R三里就是一组基。')+
D('C16o','claude_explain','(2)：还是 [U | V] 消元。先把第 3 行换到最上面当主元行——它开头是 1，免得出分数。','第二问，还是把U和V并排消元。先把第三行换到最上面当主元行，因为它开头是一，可以避免分数。')+
D('C16p','claude_explain','一路消下去：R₂ − 3R₁、R₃ − 2R₁，交换 R₂、R₃，R₃ − 2R₂ 再乘 −1，最后回代。右边得到 S = [[−2, −3, 7], [3, 5, −10], [1, 1, −2]]。','一路消下去：第二行减三倍第一行，第三行减两倍第一行，交换第二、三行，第三行减两倍第二行，再乘负一，最后往上回代。右边得到S：负二、负三、七；三、五、负十；一、一、负二。')+
D('G03c','gpt_point','自检第 1 列：−2(2, 3, 1) + 3(1, 2, 0) + (2, 0, 3) = (1, 0, 1) = v₁。对。','自检第一列：负二倍u一，加三倍u二，再加u三，算出来是一、零、一，正好是v一。对。')+
D('C16q','claude_point','最后一个变式，倒着问：2015–2016 卷第 3 题。v₁ = (2, 6)，v₂ = (1, 4)，S = [[4, 1], [2, 1]] 是 {v} 到 {u} 的过渡矩阵，求 u₁、u₂。','最后一个变式，倒过来问：二零一五到二零一六学年卷，第三题。已知v一、v二，和过渡矩阵S，求u一、u二。')+
D('D04b','ds_confused','倒着问？那是不是还要先求 S 的逆……','倒着问？那是不是还要先求S的逆？',mood='think')+
D('C16r','claude_explain','不必。S 的每一列，就是 v 在 u 下的坐标：第 1 列 (4, 2) 说 v₁ = 4u₁ + 2u₂；第 2 列 (1, 1) 说 v₂ = u₁ + u₂。','不必。记住一句话：S的每一列，就是v在u下的坐标。第一列四、二，说的是v一等于四u一加二u二；第二列一、一，说的是v二等于u一加u二。')+
D('C16s','claude_explain','解这个小方程组：u₂ = v₂ − u₁，代入得 v₁ = 2u₁ + 2v₂。所以 u₁ = (v₁ − 2v₂)/2 = (0, −1)，u₂ = v₂ − u₁ = (1, 5)。','解这个小方程组：由第二式，u二等于v二减u一；代进第一式，v一等于二u一加二v二。所以u一等于v一减二v二，再除以二，得零、负一；u二等于v二减u一，得一、五。')+
D('G03d','gpt_point','验：4(0, −1) + 2(1, 5) = (2, 6) = v₁；(0, −1) + (1, 5) = (1, 4) = v₂。全对。','验算：四倍的零、负一，加两倍的一、五，得二、六，正是v一；零、负一加一、五，得一、四，正是v二。全对。')
)
ins(p,{'C16f':blk})
